import { Router } from "express";
import { requireAuth } from "../../../platform/security/identity/middleware/requireAuth.js";
import { requirePermission } from "../../../platform/security/identity/middleware/requirePermission.js";
import { endNotlaufController, getSystemDatabaseRoutingController, getSystemDatabaseTargetsController, getNotlaufStatusController, getSystemConfigController, pingSystemDatabaseController, replaySystemJsonEmergencyController, startNotlaufController, syncNotlaufFilesController, runSystemDatabaseFullSyncController, updateSystemDatabaseRoutingController, updateSystemDatabaseTargetController, updateSystemConfigController, } from "./system-config.controller.js";
export const systemSystemConfigRouter = Router();
systemSystemConfigRouter.get("/", getSystemConfigController);
systemSystemConfigRouter.put("/", updateSystemConfigController);
systemSystemConfigRouter.patch("/", updateSystemConfigController);
systemSystemConfigRouter.post("/database/ping", requireAuth, requirePermission("SYSTEM_ADMIN"), pingSystemDatabaseController);
systemSystemConfigRouter.get("/database", requireAuth, requirePermission("SYSTEM_ADMIN"), getSystemDatabaseTargetsController);
systemSystemConfigRouter.put("/database", requireAuth, requirePermission("SYSTEM_ADMIN"), updateSystemDatabaseTargetController);
systemSystemConfigRouter.get("/database/routing", requireAuth, requirePermission("SYSTEM_ADMIN"), getSystemDatabaseRoutingController);
systemSystemConfigRouter.put("/database/routing", requireAuth, requirePermission("SYSTEM_ADMIN"), updateSystemDatabaseRoutingController);
systemSystemConfigRouter.post("/database/full-sync", requireAuth, requirePermission("SYSTEM_ADMIN"), runSystemDatabaseFullSyncController);
systemSystemConfigRouter.post("/database/json-emergency/replay", requireAuth, requirePermission("SYSTEM_ADMIN"), replaySystemJsonEmergencyController);
systemSystemConfigRouter.get("/notlauf", getNotlaufStatusController);
systemSystemConfigRouter.post("/notlauf/start", startNotlaufController);
systemSystemConfigRouter.post("/notlauf/sync", syncNotlaufFilesController);
systemSystemConfigRouter.post("/notlauf/end", endNotlaufController);
